parse_package <- function(x) {
  even <- x[seq(2, length(x) - 1)]
  odd <- x[seq(3, length(x))]
  results <- map2(even, odd, function(check, result) {
    structure(
      list(
        status = result$value,
        check = check$value,
        results = result$extra
      ),
      class = "result"
    )
  })

  structure(
    list(
      name = x[[1]]$value,
      results = results
    ),
    class = "package"
  )
}

